DO $monaco_initialize$
DECLARE role_state record;
BEGIN
  IF current_database() <> 'monaco_ledger' OR session_user <> 'monaco_ledger_owner' THEN
    RAISE EXCEPTION 'Wrong isolated ledger identity';
  END IF;
  SELECT * INTO STRICT role_state FROM pg_roles WHERE rolname = 'monaco_ledger_runner';
  IF role_state.rolcanlogin OR role_state.rolsuper OR role_state.rolcreatedb OR role_state.rolcreaterole OR role_state.rolinherit OR role_state.rolreplication OR role_state.rolbypassrls
     OR EXISTS (SELECT 1 FROM pg_auth_members WHERE member=role_state.oid) THEN
    RAISE EXCEPTION 'Restricted-role precondition failed';
  END IF;
  IF current_setting('log_statement') <> 'none'
     OR coalesce(current_setting('pg_stat_statements.track',true),'top') NOT IN ('top','none')
     OR coalesce(current_setting('pgaudit.log',true),'none') NOT IN ('none','') THEN
    RAISE EXCEPTION 'Secret-free logging precondition failed';
  END IF;
  BEGIN
    EXECUTE format('ALTER ROLE %I PASSWORD %L','monaco_ledger_runner',
      pg_catalog.gen_random_uuid()::text || pg_catalog.gen_random_uuid()::text);
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION USING MESSAGE='Restricted credential initialization failed; details suppressed', ERRCODE='P0001';
  END;
END
$monaco_initialize$;
